/*
 * magnification-large. It draws itself in, then its window becomes magnification-small's: the outline flows into the other drawing's,
 * holds, and flows back. Bring the pointer near and it turns toward the other.
 * Generated by dogfood/hard/generate.py from the owner's story (dogfood/HARD.md); measured, not read off by eye.
 */
const { icon, spring, stepS, register, pointer, disposer, story, clamp, smooth, SPRING } = IF;

function mount({ stage, svg, read, src }, reach) {
  const bag = disposer();
  const ic = icon(svg, src);
  const [opening] = ic.hole(0);
  const front = ic.part("front", [0], { paint: "first" });
  ic.part("side", [2]);
  const win = ic.part("window", [opening, 1]);
  win.hi(true);
  const S = front.extent("u-up"), W = win.extent("u-up");
  /* magnification-small's window, as fractions of its own screen (measured with the kernel), placed on this screen */
  const OTHER = [[0.3207, 0.5992], [0.3154, 0.5929], [0.3099, 0.5872], [0.3041, 0.5821], [0.2982, 0.5776], [0.2923, 0.5738], [0.2864, 0.5707], [0.2805, 0.5681], [0.2748, 0.5661], [0.2691, 0.5646], [0.2636, 0.5635], [0.2582, 0.5628], [0.253, 0.5625], [0.2478, 0.5625], [0.2428, 0.5628], [0.2379, 0.5633], [0.2331, 0.5641], [0.2285, 0.5652], [0.2239, 0.5666], [0.2196, 0.5681], [0.2153, 0.57], [0.2112, 0.572], [0.2072, 0.5743], [0.2033, 0.5767], [0.1996, 0.5794], [0.196, 0.5823], [0.1925, 0.5853], [0.1891, 0.5885], [0.1858, 0.5918], [0.1827, 0.5953], [0.1796, 0.599], [0.1767, 0.6027], [0.1739, 0.6067], [0.1712, 0.6107], [0.1686, 0.6149], [0.1662, 0.6193], [0.1639, 0.6238], [0.1617, 0.6284], [0.1597, 0.6333], [0.1579, 0.6382], [0.1562, 0.6434], [0.1547, 0.6487], [0.1534, 0.6542], [0.1523, 0.6599], [0.1514, 0.6657], [0.1507, 0.6717], [0.1503, 0.6778], [0.15, 0.6841], [0.15, 0.6906], [0.1503, 0.6972], [0.1508, 0.704], [0.1516, 0.7109], [0.1528, 0.718], [0.1544, 0.7252], [0.1565, 0.7326], [0.159, 0.74], [0.1621, 0.7474], [0.1657, 0.7548], [0.1699, 0.7621], [0.1744, 0.7691], [0.1794, 0.7757], [0.1847, 0.7819], [0.1903, 0.7877], [0.196, 0.7928], [0.2019, 0.7973], [0.2079, 0.8012], [0.2138, 0.8043], [0.2196, 0.8069], [0.2254, 0.8089], [0.231, 0.8104], [0.2365, 0.8115], [0.2419, 0.8122], [0.2471, 0.8125], [0.2523, 0.8125], [0.2573, 0.8122], [0.2622, 0.8117], [0.267, 0.8109], [0.2716, 0.8098], [0.2762, 0.8084], [0.2805, 0.8068], [0.2848, 0.805], [0.2889, 0.8029], [0.2929, 0.8007], [0.2968, 0.7982], [0.3005, 0.7956], [0.3042, 0.7927], [0.3077, 0.7897], [0.311, 0.7865], [0.3143, 0.7832], [0.3175, 0.7797], [0.3205, 0.776], [0.3234, 0.7723], [0.3262, 0.7683], [0.3289, 0.7643], [0.3315, 0.7601], [0.3339, 0.7557], [0.3362, 0.7512], [0.3384, 0.7465], [0.3404, 0.7417], [0.3422, 0.7367], [0.3439, 0.7315], [0.3453, 0.7262], [0.3466, 0.7207], [0.3477, 0.715], [0.3486, 0.7092], [0.3493, 0.7032], [0.3497, 0.6971], [0.35, 0.6907], [0.35, 0.6843], [0.3497, 0.6777], [0.3492, 0.6709], [0.3484, 0.664], [0.3472, 0.6569], [0.3456, 0.6497], [0.3436, 0.6423], [0.341, 0.6349], [0.338, 0.6275], [0.3344, 0.6201], [0.3303, 0.6128], [0.3257, 0.6058]];
  const target = OTHER.map(([fa, fb]) => S.pt(S.a[0] + fa * (S.a[1] - S.a[0]), S.b[0] + fb * (S.b[1] - S.b[0])));
  const shape = ic.morph(opening, target, { hide: [1] }); // its inner wall belongs to its own outline
  const life = story(stage, {
    rest: { become: 0, ink: 1 },
    poster: { become: 1, ink: 1 },
    intro: { dur: 3000, from: { ink: 0 }, ease: "linear" },
    beats: [
      { dur: 1000 },
      { dur: 900, to: { become: 1 } },  // it becomes the other
      { dur: 1500 },
      { dur: 900, to: { become: 0 } },  // and itself again
      { dur: 900 },
    ],
  });
  const hand = spring(0, SPRING.hand);
  let max = reach, label = "";
  const centre = W.pt((W.a[0] + W.a[1]) / 2, (W.b[0] + W.b[1]) / 2);
  const loop = register(stage, (dt) => {
    const x = life.step(dt), y = stepS(hand, dt);
    const v = life.values(life.held ? { become: hand.x } : {});
    ic.ink(v.ink);
    const t = v.become * max;
    shape.set(t);
    const shown = v.ink < 1 ? "drawing" : t < 0.02 ? "rest" : `small ${Math.round(t * 100)}%`;
    if (shown !== label) { read.textContent = shown; label = shown; }
    return x || y;
  });
  const leave = () => { life.hold(false); loop.wake(); };
  bag.add(pointer(stage, {
    move(pt) {
      const near = 1 - smooth(30, 170, Math.hypot(pt[0] - centre[0], pt[1] - centre[1]));
      if (near <= 0) { leave(); return; }
      if (!life.held) { hand.x = life.values().become; life.hold(true); }
      hand.t = near;
      loop.wake();
    },
    leave,
  }));
  bag.add(() => { loop.unregister(); while (svg.firstChild) svg.firstChild.remove(); });
  return { set(v) { max = clamp(v, 0, 1); loop.wake(); }, destroy: bag.dispose };
}

isoform({
  name: "magnification-large",
  icon: "magnification-large",
  variant: "rounded-left",
  means: "Its window flows into magnification-small's outline, holds, and flows back.",
  rules: [5, 8, 9],
  range: [0.6, 0.85, 1],
  mount,
});
